    bytes32 public constant MINT = keccak256("MINT");

    constructor() {
        _setRoleAdmin(MINT, DEFAULT_ADMIN_ROLE);
        _grantRole(DEFAULT_ADMIN_ROLE, msg.sender);
    }

    modifier onlyVault() {
        require(
            hasRole(MINT, msg.sender),
            "VaultOwned: caller is not the Vault"
        );
        _;
    }
